-- What each industry makes (data/industries/industries.json) and the official figures for 2025
-- (data/industries/qcew-2025.json: U.S. Bureau of Labor Statistics, Quarterly Census of Employment and Wages, retrieved 2026-11-18).
-- Generated by scripts/build-industry-stats-sql.mjs. Edit the JSON and regenerate; once this
-- file has been applied anywhere, a change goes out as a new migration instead.
-- Idempotent: rows are matched by key and brought up to date; nothing is deleted.

INSERT INTO "industry_profiles" ("code", "name", "summary") VALUES
  ('311', 'Food Manufacturing', 'Plants that turn crops, milk and livestock into food: meat, dairy, baked goods, snacks and animal feed.'),
  ('312', 'Beverage and Tobacco Product Manufacturing', 'Bottlers, breweries, wineries and distilleries, and the plants that make cigarettes and other tobacco products.'),
  ('313', 'Textile Mills', 'Mills that spin fiber into yarn and thread, and weave, knit and finish fabric.'),
  ('314', 'Textile Product Mills', 'Plants that make goods from fabric other than clothing: carpet, linens, canvas, rope and bags.'),
  ('315', 'Apparel Manufacturing', 'Plants that cut and sew clothing, and mills that knit it.'),
  ('316', 'Leather and Allied Product Manufacturing', 'Tanneries, and plants that make footwear, luggage, belts and other leather goods.'),
  ('321', 'Wood Product Manufacturing', 'Sawmills, and plants that make lumber, plywood, trusses, flooring, pallets and manufactured homes.'),
  ('322', 'Paper Manufacturing', 'Mills that make pulp, paper and paperboard, and plants that turn them into boxes, bags and tissue.'),
  ('323', 'Printing and Related Support Activities', 'Plants that print books, labels, packaging, signs and forms, and the shops that prepare and finish the work.'),
  ('324', 'Petroleum and Coal Products Manufacturing', 'Refineries that turn crude oil into fuels, and plants that make asphalt, roofing materials and lubricants.'),
  ('325', 'Chemical Manufacturing', 'Plants that make basic chemicals, plastic resins, fertilizer, medicines, paints, soaps and cosmetics.'),
  ('326', 'Plastics and Rubber Products Manufacturing', 'Plants that mold, extrude and form plastic and rubber into parts, pipe, film, bottles, foam, hoses and tires.'),
  ('327', 'Nonmetallic Mineral Product Manufacturing', 'Plants that make glass, cement, concrete, brick, tile, lime and gypsum products from sand, stone and clay.'),
  ('331', 'Primary Metal Manufacturing', 'Mills, smelters and foundries that make steel, aluminum, copper and other metals, and shape them into plate, bar, pipe, wire and castings.'),
  ('332', 'Fabricated Metal Product Manufacturing', 'Shops and plants that cut, form, weld, machine and coat metal into structural steel, tanks, hardware, tools, valves and precision parts.'),
  ('333', 'Machinery Manufacturing', 'Plants that build machines: farm, construction and oilfield equipment, engines, pumps, compressors, heating and cooling units, and the machinery other factories run on.'),
  ('334', 'Computer and Electronic Product Manufacturing', 'Plants that make semiconductors, circuit boards, computers, communications equipment, and measuring, medical and navigation instruments.'),
  ('335', 'Electrical Equipment, Appliance, and Component Manufacturing', 'Plants that make lighting, household appliances, motors, generators, transformers, switchgear, batteries, wire and cable.'),
  ('336', 'Transportation Equipment Manufacturing', 'Plants that build cars, trucks, trailers, aircraft, spacecraft, rail cars, ships and boats, and the parts that go into them.'),
  ('337', 'Furniture and Related Product Manufacturing', 'Plants that make household and office furniture, kitchen cabinets, mattresses, shelving and store fixtures.'),
  ('339', 'Miscellaneous Manufacturing', 'Plants that make medical devices and supplies, and goods that fit no other industry: jewelry, sporting goods, toys, signs and office supplies.')
ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name", "summary" = EXCLUDED."summary";

